// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · Genel ek sorular: Sınav Hazırlık kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: TYT Türkçe: sözcükte ve cümlede anlam (her soru kendi cümlesini içerir) | TYT Türkçe: kısa paragrafta anlam (her soru kendi kısa paragrafını içerir) | Sayısal mantık ve problemler (yaş, işçi, hareket, yüzde, karışım; her soru özgün) | Sözel mantık ve akıl yürütme (sıralama, eşleştirme, koşullu çıkarım; her soru kendi verisini içerir)) (zor).
const ozExam5Zor = <(String, String, List<String>, String)>[
  ('"Dündeki toplantıya katılamadım." cümlesindeki yazım yanlışının nedeni hangisidir?', 'Zaman bildiren sözcüklere ilgi eki -ki doğrudan getirilir, araya -de girmez.', ['Zaman bildiren sözcüklere -ki eki hiçbir biçimde getirilemez, çünkü bu ek yalnız yer bildirir.', 'Dün sözcüğü büyük harfle yazılmalıdır.', 'Ki eki ünlü uyumuna girmek zorundadır.'], 'Doğrusu "dünkü toplantı"dır. Zaman sözcüklerine -ki doğrudan eklenir (dünkü, yarınki, akşamki); bulunma eki yer bildiren adlarla kullanılır (evdeki).'),
  ('Aşağıdaki birleşik fiillerden hangisi, birleşme sırasında hiçbir ses olayı olmadığı için ayrı yazılır?', 'fark etmek', ['reddetmek', 'seyretmek', 'zannetmek'], '"Fark" sözcüğü "etmek" ile birleşirken ses değişmez, bu yüzden "fark etmek" ayrı yazılır. "Reddetmek" (ret), "seyretmek" (seyir) ve "zannetmek" (zan) ses olayı içerdiği için bitişiktir.'),
  ('Aşağıdaki cümlelerin hangisinde "-ki" eki, ait olma (aitlik) anlamıyla bir zamirin yerini tutan bir sözcük oluşturmuştur?', 'Benim bisikletim eski, onunki yepyeni.', ['Kapının önündeki ayakkabılar kimin?', 'Bildim ki bu iş kolay bitmeyecek.', 'Sabahki derste konu bitirildi.'], '"Onunki" sözünde -ki, "onun bisikleti" yerine kullanılan bir zamir türetmiştir. "Önündeki" ve "sabahki" sözlerinde -ki sıfat yapar; "bildim ki" ise bağlaçtır.'),
  ('Aşağıdaki cümlelerin hangisinde küçük harfle yazılmış bir sözcük, gök cismi adı olarak kullanıldığı için büyük harfle başlamalıdır?', 'Dolunay gecesinde ay, gökyüzünü aydınlatıyordu.', ['Çamaşırları güneşte kuruttuk.', 'Bütün dünya bu sabahki haberi konuşuyor.', 'Bu ayın faturası yüksek geldi.'], 'Gök cismi olarak kullanılan "Ay" büyük harfle yazılır. "Güneşte" güneş ışığı, "dünya" insanlar, "bu ay" ise takvim dilimi anlamındadır ve küçük harfle yazılır.'),
  ('Küçük harfle yazılan ölçü kısaltmalarına gelen ekler, kısaltmanın okunuşuna değil açılımına göre getirilir. Buna göre hangisi doğrudur?', '5 kg\'dan fazla bagaj ücretlidir.', ['5 kg\'den fazla bagaj ücretlidir.', '5 kg\'ten fazla bagaj ücretlidir.', '5 kgdan fazla bagaj ücretlidir.'], '"kg" kısaltması "kilogram" diye okunur; eki de buna göre alır: kilogramdan → kg\'dan. Ek kesmeyle ayrılır.'),
  ('Aşağıdaki cümlelerin hangisinde kesme işareti kurala aykırı olarak kullanılmıştır?', 'Dilekçemi Türk Dil Kurumu\'na gönderdim.', ['Bu yaz tatil için Bodrum\'a gideceğiz.', 'Yunus Emre\'nin şiirlerini severim.', 'Bu kitabı Ayşe\'den ödünç aldım.'], 'Kurum ve kuruluş adlarına gelen ekler kesmeyle ayrılmaz: "Türk Dil Kurumuna". Kişi ve yer adlarına gelen çekim ekleri ise kesmeyle ayrılır.'),
  ('"Türkçe\'nin" yazımı yanlış kabul edilir. Bunun nedeni hangisidir?', 'Yapım ekiyle türemiş dil adlarına gelen ekler kesmeyle ayrılmaz.', ['Dil adları küçük harfle yazılmalıdır.', 'Tamlayan eki, dil adlarına hiçbir durumda getirilemeyen bir ektir.', 'Kesme işareti yalnız rakamlarda kullanılır.'], '"Türkçe" sözcüğü "Türk" adına -çe yapım eki getirilerek türetilmiştir. Bu tür sözcüklere gelen çekim ekleri bitişik yazılır: Türkçenin, Fransızcada.'),
  ('"Bir insan ( ) güvendiği dostu tarafından aldatılırsa ne yapar ( )" cümlesinde ayraç içlerine sırasıyla hangi işaretler gelmelidir?', 'virgül, soru işareti', ['iki nokta, nokta', 'noktalı virgül, ünlem', 'virgül, nokta'], 'Özneden sonra gelen ve uzun bir yan cümle başlatan yere, anlam karışıklığını önlemek için virgül konur. Cümle soru bildirdiği için sonuna soru işareti gelir.'),
  ('"Ödevlerini bitiren, öğrenciler bahçeye çıkabilir." cümlesindeki virgül neden yanlıştır?', 'Sıfat ile nitelediği ad arasına virgül konmaz.', ['Cümle sonuna ünlem gerektiği için', 'Cümlenin yüklemi eksik olduğu için', 'Virgül yalnız sayıların arasında kullanıldığı için'], '"Ödevlerini bitiren" sözü "öğrenciler" adını niteleyen bir sıfat öbeğidir. Sıfat ile nitelediği adı virgülle ayırmak anlamı bozar.'),
  ('Aşağıdaki sözcüklerin hangisinde birden çok ses olayı birlikte görülür?', 'kaybı', ['ağacı', 'burnu', 'dolabı'], '"Kayıp" sözcüğü ünlüyle başlayan ek alınca hem ikinci hecedeki "ı" düşer hem de "p" yumuşar: kaybı. Öteki seçeneklerin her birinde yalnız bir ses olayı vardır.'),
  ('"Dondurma" sözcüğü, yapısı bir fiilimsiye benzese de neden fiilimsi sayılmaz?', 'Bir nesnenin kalıcı adı olmuş, fiil anlamını yitirmiştir.', ['Kökü fiil değil, isim olduğu ve ek almadığı için', 'İçinde hiçbir ek bulunmadığı için', 'Yalnız cümle sonunda kullanılabildiği için'], '"Dondurma" bir yiyeceğin kalıcı adıdır; eylem bildirmez. Fiilimsiler ise geçici olarak ad, sıfat ya da zarf görevi üstlenir ve fiil anlamını korur.'),
  ('Aşağıdaki cümlelerin hangisinde "aşağı" sözcüğü yön zarfı olarak kullanılmıştır?', 'Merdivenlerden koşarak aşağı indi.', ['Aşağıdaki odadan sesler geliyordu.', 'Aşağıya bakınca başı döndü.', 'Aşağısı bu akşam çok kalabalıktı.'], 'Yön bildiren sözcükler ek almadan bir fiili nitelediğinde yön zarfı olur: "aşağı indi". Ek aldıklarında ad ya da sıfat görevine geçerler.'),
  ('Aşağıdaki cümlelerin hangisinde "ne" sözcüğü soru zamiri olarak kullanılmıştır?', 'Masanın üstünde ne var?', ['Ne güzel bir gün!', 'Bu ara ne kitap okuyorsun?', 'Ne çay ne kahve içti.'], '"Ne var?" sorusunda "ne" bir varlığın yerini tutarak soru sorduğu için soru zamiridir. "Ne kitap" sözünde soru sıfatı, "ne güzel" sözünde zarf, "ne ... ne" kalıbında bağlaçtır.'),
  ('"Gelme!" sözcüğündeki "-me" eki neden isim-fiil eki sayılmaz?', 'Burada olumsuzluk ekidir, sözcük çekimli bir emir fiilidir.', ['İsim-fiil eki yalnız "-mak" biçiminde olabilir; "-me" biçimi yoktur.', 'Sözcük tek heceli olduğu için fiilimsi olamaz.', 'Ünlem işareti fiilimsileri çekimli fiile dönüştürür.'], '"Gelme!" emir kipinin olumsuz biçimidir ve kendi başına yargı bildirir. İsim-fiil eki olan "-me" ise eylemi ada dönüştürür: "Gelmesi gecikti."'),
  ('"Bu şehre geleli üç yıl oldu." cümlesindeki "-eli" zarf-fiil eki hangi anlamı verir?', 'Bir eylemin başladığı andan beri geçen süreyi', ['Eylemin hemen ardından gelen bir başka eylemi', 'Bir eylemin koşulunu', 'Eylemin hangi biçimde, nasıl yapıldığını'], '"-alı/-eli" eki "-den beri" anlamı katar: "geleli" = geldiğimden beri.'),
  ('"Annem bana bir kazak ördürdü." cümlesinde yüklemin çatısıyla ilgili hangisi doğrudur?', 'Ettirgendir; eylemi özne başkasına yaptırmıştır.', ['Edilgendir; eylemi yapan belli değildir.', 'Dönüşlüdür; eylemden yalnızca özne kendisi etkilenmiştir.', 'İşteştir; eylem karşılıklı yapılmıştır.'], '"Ör-" fiiline "-dür" ettirgenlik eki getirilmiştir: anne kazağı kendisi örmemiş, başkasına örmesini sağlamıştır.'),
  ('"Öğretmen, ödevleri bitiren öğrencilere birer kitap verdi." cümlesinde dolaylı tümleç kaç sözcükten oluşur?', 'Üç', ['İki', 'Bir', 'Dört'], '"Kime verdi?" sorusunun yanıtı sıfat-fiil öbeğiyle birlikte "ödevleri bitiren öğrencilere"dir. "Ödevleri" bu öbeğin içinde yer alır, ayrı bir öğe değildir.'),
  ('"Bütün öğrenciler sınavı kazanamadı." cümlesi hangi nedenle anlatım bozukluğu içerir?', 'Kimsenin mi, bazılarının mı kazanamadığı belirsizdir.', ['Cümlenin yüklemi gereğinden uzundur.', '"Sınavı" sözcüğü gereksiz yere belirtme eki almıştır.', 'Öznesi çoğul olduğu hâlde yüklemi tekil kişiyle çekimlenmiştir.'], 'Cümle hem "hiçbir öğrenci kazanamadı" hem de "öğrencilerin hepsi kazanamadı, bazıları kazandı" biçiminde anlaşılabilir. Bu bir anlam belirsizliğidir.'),
  ('Bir adada yaşayanlar ya her zaman doğru söyleyen doğrucular ya da her zaman yalan söyleyen yalancılardır. A "B doğrucudur." diyor; B ise "A ile ben farklı türdeniz." diyor. Buna göre A ve B hangi türdendir?', 'İkisi de yalancıdır.', ['A doğrucu, B yalancıdır.', 'A yalancı, B doğrucudur.', 'İkisi de doğrucudur.'], 'A doğrucu olsaydı B de doğrucu olurdu; o zaman B\'nin "farklıyız" sözü yanlış çıkardı. Bu çelişki A\'nın yalancı olduğunu gösterir; A\'nın sözü yanlış olduğundan B de yalancıdır ve "farklıyız" sözü gerçekten yanlıştır.'),
  ('Bir okulda resim kursuna 20, müzik kursuna 25, tiyatro kursuna 15 öğrenci kayıtlıdır. Resim ve müziğe 8, resim ve tiyatroya 5, müzik ve tiyatroya 7 öğrenci kayıtlıdır; üç kursa birden 3 öğrenci gitmektedir. En az bir kursa kayıtlı kaç öğrenci vardır?', '43', ['60', '40', '46'], 'Üç küme için birleşim: 20+25+15−8−5−7+3 = 43. İkili kesişimler çıkarılınca üçlü kesişim tamamen silindiği için onu bir kez geri eklemek gerekir.'),
  ('40 kişilik bir sınıfta 24 öğrenci satranç, 21 öğrenci de bilim kulübüne üyedir. Hiçbir kulübe üye olmayan öğrenci sayısı en çok kaç olabilir?', '16', ['19', '5', '21'], 'Hiçbir kulübe üye olmayanların sayısı, birleşim en küçük olduğunda en büyüktür. Bilim kulübünün bütün üyeleri satranç kulübünde de olursa birleşim 24 olur; 40−24 = 16.'),
  ('"Bütün A\'lar B\'dir." önermesi doğru ise aşağıdakilerden hangisi de kesinlikle doğrudur?', 'B olmayan hiçbir şey A değildir.', ['Bütün B\'ler aynı zamanda A\'dır.', 'Bazı B\'ler A değildir.', 'A olmayan hiçbir şey B değildir.'], 'A kümesi B\'nin içindedir; B\'nin dışındaki bir öge A\'da olamaz. B\'nin A\'dan büyük olup olmadığı ise bilinmez; bu yüzden öteki seçenekler kesin değildir.'),
  ('"Hiçbir tembel kişi başarılı değildir. Bazı öğrenciler başarılıdır." önermelerine göre hangisi kesinlikle doğrudur?', 'Bazı öğrenciler tembel değildir.', ['Bütün öğrenciler başarılı kişilerdir.', 'Bazı tembeller öğrencidir.', 'Hiçbir öğrenci tembel değildir.'], 'Başarılı olan öğrenciler, hiçbir tembel başarılı olmadığı için tembel olamaz. Demek ki en az bazı öğrenciler tembel değildir. Öteki öğrencilerin tembel olup olmadığı ise bilinmez.'),
  ('"Ali yorgundur ya da açtır." önermesinin değili (olumsuzu) hangisidir?', 'Ali ne yorgundur ne de açtır.', ['Ali yorgun değildir ya da aç değildir.', 'Ali hem yorgundur hem açtır.', 'Ali yorgundur ama aç değildir.'], '"p veya q" önermesinin değili "p değil ve q değil" önermesidir (De Morgan kuralı). Ali\'nin iki durumdan hiçbirinde olmaması gerekir.'),
  ('"Sürücü belgesi olmayan kimse araç kullanamaz." kuralına göre sürücü belgesine sahip olmak, araç kullanmak için ne tür bir koşuldur?', 'Gerekli ama yeterli olmayan bir koşul', ['Hem gerekli hem yeterli bir koşul', 'Yeterli olan ama hiç gerekli olmayan bir koşul', 'Ne gerekli ne yeterli bir koşul'], 'Belgesi olmayan araç kullanamaz; demek ki belge gereklidir. Ama belgesi olan herkesin araç kullandığı söylenmemiştir (aracı olmayabilir), bu yüzden yeterli değildir.'),
  ('Kenarları 120 m ve 84 m olan dikdörtgen bir arazinin çevresine, köşelere de gelecek biçimde eşit aralıklarla ağaç dikilecektir. En az kaç ağaç gerekir?', '34', ['36', '17', '408'], 'Aralık EBOB(120, 84) = 12 m olmalıdır. Kapalı bir çevrede ağaç sayısı aralık sayısına eşittir: 2·(120+84)/12 = 34.'),
  ('Boyutları 4 cm, 6 cm ve 10 cm olan özdeş tuğlalar aynı yönde dizilerek içi dolu bir küp oluşturulacaktır. En az kaç tuğla gerekir?', '900', ['240', '60', '1800'], 'Küpün kenarı 4, 6 ve 10\'un EKOK\'u olmalıdır: 60 cm. Her doğrultudaki tuğla sayısı 15, 10 ve 6\'dır; 15·10·6 = 900.'),
  ('Bir kutudaki bilyeler 6\'şarlı, 8\'erli ve 9\'arlı paketlere ayrılmak istendiğinde her seferinde son pakete 1 bilye eksik kalıyor. Kutuda en az kaç bilye vardır?', '71', ['73', '143', '72'], 'Bilye sayısının 1 fazlası 6, 8 ve 9\'a tam bölünür. EKOK(6, 8, 9) = 72 olduğundan en küçük sayı 72 − 1 = 71\'dir.'),
  ('A şehri B şehrinden 6 saat ileridedir. İki şehirdeki ofisler de yerel saatle 09.00-17.00 arasında çalışıyor. İki ofisin aynı anda açık olduğu süre kaç saattir?', '2', ['6', '8', 'Hiç yok'], 'A\'daki 09.00-17.00, B saatiyle 03.00-11.00\'e karşılık gelir. B ofisi 09.00\'da açıldığından ortak süre 09.00-11.00 arası, yani 2 saattir.'),
  ('Elinde yeterince 5 TL, 10 TL ve 20 TL\'lik banknot bulunan biri, 30 TL\'yi kaç farklı biçimde ödeyebilir? (Banknotların sırası önemli değildir.)', '6', ['4', '5', '10'], '20\'lik kullanılırsa kalan 10 TL iki biçimde (10 ya da 5+5), kullanılmazsa 30 TL dört biçimde (10\'luk sayısı 0, 1, 2, 3) ödenir. Toplam 2 + 4 = 6.'),
  ('Yalnız 3 TL\'lik ve 5 TL\'lik pullar kullanılarak tam olarak ödenemeyen en büyük tutar kaç TL\'dir?', '7', ['8', '2', '11'], '8 = 3+5, 9 = 3·3, 10 = 5·2 olur ve sonra her tutar 3 ekleyerek elde edilir. 7 ise bu pullarla elde edilemez; 3·5 − 3 − 5 = 7 kuralı da bunu doğrular.'),
  ('"Bu romanı çok sevdim ama okurların pek ilgisini çekmedi." cümlesindeki anlatım bozukluğunun nedeni hangisidir?', 'İkinci yargının öznesi söylenmemiştir.', ['Cümlede gereksiz bir sözcük vardır.', 'Yüklemler farklı zamanla çekimlenmiştir.', 'Karşıtlık bağlacı yanlış yerde kullanılmıştır.'], 'Birinci yargının öznesi "ben", ikincisinin öznesi ise "roman"dır. Özne değiştiği hâlde ikinci yargıda belirtilmemiştir; "ama o, okurların..." denmelidir.'),
  ('"Bu çanta seninkinden daha büyük." cümlesinde "daha" sözcüğü hangi görevdedir?', 'Karşılaştırma yapan bir zarftır.', ['Bir adı niteleyen sıfattır.', 'Bir adın yerini tutan zamirdir.', 'İki cümleyi birbirine bağlayan bağlaçtır.'], '"Daha" sözcüğü "büyük" sıfatının derecesini karşılaştırma yoluyla belirleyen bir miktar (derecelendirme) zarfıdır.'),
];
